def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    from collections import Counter
    counts=Counter(v for row in g for v in row)
    bg=counts.most_common(1)[0][0]
    # The sparse interior color is the signal color; its original pixels become 4.
    # Find runs of a non-background color on the perimeter.
    edge_counts=Counter()
    for c in range(w):
        if g[0][c]!=bg: edge_counts[g[0][c]]+=1
        if g[h-1][c]!=bg: edge_counts[g[h-1][c]]+=1
    for r in range(h):
        if g[r][0]!=bg: edge_counts[g[r][0]]+=1
        if g[r][w-1]!=bg: edge_counts[g[r][w-1]]+=1
    border=max(edge_counts, key=edge_counts.get)
    signal=next((v for v,n in counts.items() if v not in (bg,border) and n < max(10, h*w//4)), None)
    if signal is None:
        return g
    # Bars on horizontal edges cast vertical fills across their aligned columns.
    top=[c for c in range(w) if g[0][c]==border]
    bot=[c for c in range(w) if g[h-1][c]==border]
    if top or bot:
        cols=set(top+bot)
        for r in range(1,h-1):
            for c in cols:
                if g[r][c]==bg: g[r][c]=signal
    # Bars on vertical edges cast horizontal fills. For rows with an interior
    # signal, extend it toward the nearest side bar. Empty marked rows extend inward.
    left=[r for r in range(h) if g[r][0]==border]
    right=[r for r in range(h) if g[r][w-1]==border]
    if len(left)<2: left=[]
    if len(right)<2: right=[]
    sparse_count=sum(1 for row in grid for v in row if v==signal)
    for r in set(left+right):
        marks=[c for c in range(w) if grid[r][c]==signal]
        # With a single interior seed between opposite side bars, the far
        # side's leading edge row is also projected (the remaining bar rows are guides).
        if sparse_count==1 and left and right and not marks and r!=min(left):
            continue
        if marks:
            c=marks[0]
            if r in right:
                for j in range(c+1,w-1): g[r][j]=signal
            if r in left:
                for j in range(1,c): g[r][j]=signal
        else:
            if r in left:
                for j in range(1,w):
                    if g[r][j]==bg: g[r][j]=signal
            if r in right:
                for j in range(w-2,-1,-1):
                    if g[r][j]==bg: g[r][j]=signal
    # In this task, signal dots are marked as 4 after projecting the fill.
    for r in range(h):
        for c in range(w):
            if grid[r][c]==signal: g[r][c]=4
    return g

